function CardProgressionEquipmentStarUpFinishNode:OnDestroy()
    local curDojo = self:GetCurDojo()
    if checkInt(curDojo.level) == CardProgressionConstants.EquipmentLevelUpperLimit and 
            checkInt(curDojo.star) == EquipUtils.GetEquipmentStarMaxByDojo(curDojo) then
        Events.Broadcast(Constants.EventNames.CardProgressEquipSelectClear)
        Events.Broadcast(Constants.EventNames.CardProgressEquipStarUpFinish, curDojo)
    else
        EquipUtils.EnterCultivateEquipDialog(curDojo)
    end
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end
