--region private
---刷新装备道具
function CardProgressionEquipmentStarUpFinishNode:RefreshEquipmentGoods()
    local dojo = self:GetCurDojo()
    local goodsVo = goodsConfMgr:GetGoodsVoById(dojo.equipmentId)
    local equipVo = cardConfMgr:GetEquipVoById(dojo.equipmentId)
    CfUtils.SetUISwitchImage(self.ImgFurnace, goodsVo.quality)
    ---@type GoodNodeMB
    local mbEnv = CfUtils.GetLuaScr(self.GoodNode.gameObject, GoodNodePrefabPath)
    if mbEnv then
        mbEnv:Reload({dojo = dojo, goodsId = dojo.equipmentId, isShowNo = false})
    end
    CfUtils.FillText(self.TxtEquipName, goodsVo.name)
end

---刷新等级
function CardProgressionEquipmentStarUpFinishNode:RefreshStar()
    local befDojo = self:GetBefDojo()
    local curDojo = self:GetCurDojo()
    local starMax = EquipUtils.GetEquipmentStarMaxByDojo(curDojo)
    for i = 1, starMax do
        if i == 1 then
            CfUtils.SetUISwitchImage(self.ImgStarBefore, checkInt(befDojo.star) >= i and 2 or 1)
            CfUtils.SetUISwitchImage(self.ImgStarAfter, checkInt(curDojo.star) >= i and 2 or 1)
        else
            local star1 = self.StarGroupBefore.gameObject:AddChild(self.ImgStarBefore.gameObject)
            local star2 = self.StarGroupAfter.gameObject:AddChild(self.ImgStarAfter.gameObject)
            CfUtils.SetUISwitchImage(star1, checkInt(befDojo.star) >= i and 2 or 1)
            CfUtils.SetUISwitchImage(star2, checkInt(curDojo.star) >= i and 2 or 1)
        end
    end
end

---刷新属性
function CardProgressionEquipmentStarUpFinishNode:RefreshAttr()
    local befDojo = self:GetBefDojo()
    local curDojo = self:GetCurDojo()

    for i = checkInt(befDojo.star) + 1, checkInt(curDojo.star) do
        local node = CfUtils.InstantiateGo(self.ATKNumericalValue, self.NumericalUnlock)
        CfUtils.SetActive(node, true)
        local attrAdditionId = checkNumber(curDojo[string.format('attr%dId', i)])
        local attrVo = cardConfMgr:GetBasicAttrAdditionById(attrAdditionId)
        local attrName = attrVo.attrAdditionName

        local quality = curDojo[string.format('attr%dQuality', i)]
        local attrImgBg = node.transform:Find("ImgBg")
        CfUtils.SetUISwitchImage(attrImgBg, quality)
        local imgBgRare = node.transform:Find("Slider/ImgBgRare")
        EquipUtils.SwitchSubAttrColorByQuality(imgBgRare, quality)
        local value = curDojo[string.format('attr%dNum', i)]
        local percent = EquipUtils.GetSubAttrPercent(curDojo.equipmentId, attrAdditionId, value)
        local slider = node.transform:Find("Slider"):GetComponent(typeof(Slider))
        slider.value = percent
        local imgBgGlow = node.transform:Find("ImgBgGlow")
        CfUtils.SetUISwitchImage(imgBgGlow, quality)
        local imgBgLight = node.transform:Find("ImgBgLight")
        CfUtils.SetUISwitchImage(imgBgLight, quality)
        local txtAttrName = node.transform:Find("TxtAttack")
        CfUtils.FillText(txtAttrName, attrName)
        local txtAttrNum = node.transform:Find("TxtNumAfter")
        CfUtils.FillText(txtAttrNum, '+' .. attribute_format(attrVo.isConversion, value))
    end
end

---显示战力变化
function CardProgressionEquipmentStarUpFinishNode:ShowPointChange()
    local befDojo = self:GetBefDojo()
    if checkInt(befDojo.playerCardId) == 0 then return end

    local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
    local cardDojo = cardComponent:GetCardById(befDojo.playerCardId)
    local entity = CardProgressionUtils.GenerateEntityByCardDojo(cardDojo)
    local curPoint = checkInt(FormulaUtils.CalcCardCombatEffectiveness(entity))
    for k, v in pairs(entity.equipPart2Dojo) do
        if checkInt(v.id) == checkInt(befDojo.id) then
            entity.equipPart2Dojo[k] = befDojo
            break
        end
    end
    local befPoint = checkInt(FormulaUtils.CalcCardCombatEffectiveness(entity))
    CardProgressionUtils.ChangePointToast(curPoint - befPoint)
end

---获取befDojo
---@return EquipDojo
function CardProgressionEquipmentStarUpFinishNode:GetBefDojo()
    return self._befDojo
end

---获取curDojo
---@return EquipDojo
function CardProgressionEquipmentStarUpFinishNode:GetCurDojo()
    return self._curDojo
end
